module capi

// This file defines the fixed mapping between V types and the C ABI surface
// generated by `v c-api`. Unsupported types are skipped with a warning rather
// than exported with a leaking V-internal ABI.

pub fn is_result(t string) bool {
	return t.starts_with('!')
}

pub fn is_option(t string) bool {
	return t.starts_with('?')
}

pub fn unwrap(t string) string {
	if is_result(t) || is_option(t) {
		return t[1..]
	}
	return t
}

pub fn is_slice(t string) bool {
	return t.starts_with('[]')
}

pub fn slice_elem(t string) string {
	if !is_slice(t) {
		return ''
	}
	return t[2..]
}

pub fn strip_ref(t string) string {
	return if t.starts_with('&') { t[1..] } else { t }
}

fn is_supported_scalar(t string) bool {
	return t in ['string', 'bool', 'byte', 'u8', 'u16', 'u32', 'u64', 'usize', 'i8', 'i16', 'int',
		'i32', 'rune', 'i64', 'isize', 'f32', 'f64', 'voidptr']
}

fn is_supported_slice_elem(t string) bool {
	return t in ['u8', 'byte', 'i8', 'i16', 'u16', 'int', 'i32', 'u32', 'i64', 'u64', 'f32', 'f64']
}

fn scalar_v_type(t string) string {
	if t == 'string' {
		return '&char'
	}
	if t == 'bool' {
		return 'int'
	}
	if t == 'byte' {
		return 'u8'
	}
	if t == 'usize' {
		return 'u64'
	}
	if t == 'isize' {
		return 'i64'
	}
	if t == 'rune' {
		return 'int'
	}
	return t
}

fn scalar_c_type(t string) string {
	if t == 'string' {
		return 'char *'
	}
	if t == 'bool' {
		return 'int'
	}
	if t == 'byte' || t == 'u8' {
		return 'unsigned char'
	}
	if t == 'u16' {
		return 'uint16_t'
	}
	if t == 'u32' {
		return 'uint32_t'
	}
	if t == 'u64' || t == 'usize' {
		return 'uint64_t'
	}
	if t == 'i8' {
		return 'int8_t'
	}
	if t == 'i16' {
		return 'int16_t'
	}
	if t == 'int' || t == 'i32' || t == 'rune' {
		return 'int'
	}
	if t == 'i64' || t == 'isize' {
		return 'int64_t'
	}
	if t == 'f32' {
		return 'float'
	}
	if t == 'f64' {
		return 'double'
	}
	return 'void *'
}

// v_wrapper_type returns the C-compatible V type used in a generated wrapper
// declaration, or none when the type cannot cross the ABI safely.
pub fn v_wrapper_type(t string, m ApiModel) ?string {
	if is_result(t) || is_option(t) {
		return v_wrapper_type(unwrap(t), m)
	}
	base := strip_ref(t)
	if t.starts_with('&') && m.is_struct(base) {
		return 'voidptr'
	}
	if m.is_enum(base) {
		return 'int'
	}
	if m.is_struct(base) {
		return none
	}
	if is_supported_scalar(t) {
		return scalar_v_type(t)
	}
	if is_slice(t) && is_supported_slice_elem(slice_elem(t)) {
		return '&${c_prim(slice_elem(t))}'
	}
	return none
}

// c_decl_type returns the C spelling for a V type. slices and results are
// handled by the caller, which adds a length or out parameter.
pub fn c_decl_type(t string, m ApiModel) ?string {
	if is_result(t) || is_option(t) {
		return c_decl_type(unwrap(t), m)
	}
	base := strip_ref(t)
	if t.starts_with('&') && m.is_struct(base) {
		return 'void *'
	}
	if m.is_enum(base) {
		return 'int'
	}
	if m.is_struct(base) {
		return none
	}
	if is_supported_scalar(t) {
		return scalar_c_type(t)
	}
	if is_slice(t) && is_supported_slice_elem(slice_elem(t)) {
		return 'const ${scalar_c_type(slice_elem(t))} *'
	}
	return none
}

// c_elem_type returns the C spelling of a slice element for declarations.
pub fn c_elem_type(t string) string {
	return scalar_c_type(t)
}

fn c_prim(v string) string {
	if v == 'u8' || v == 'byte' {
		return 'u8'
	}
	if v == 'int' || v == 'i32' || v == 'rune' {
		return 'int'
	}
	return v
}
